import org.junit.jupiter.api.io.TempDir;

class LmdbValueLookupOptimizerTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void scalarCapturePreservesSharedIdentityWithoutNativeLookup(@TempDir Path directory) throws Exception {
		try (CountingValues values = new CountingValues(directory.toFile())) {
			Value shared = VF.createLiteral("one query-owned constant");
			ValueConstant first = new ValueConstant(shared);
			ValueConstant second = new ValueConstant(shared);
			Extension extension = new Extension(new SingletonSet(), new ExtensionElem(first, "first"),
					new ExtensionElem(second, "unused"), new ExtensionElem(Var.of("parameter", shared), "scalar-var"));
			values.lookups = 0;
			new LmdbValueLookupOptimizer(values).optimize(extension, null, EmptyBindingSet.getInstance());
			assertEquals(0, values.lookups, "scalar values are captured; native consumers prepare IDs on demand");
			assertSame(first.getValue(), second.getValue(), "shared NOW and scalar constant identity must survive");
			assertEquals(shared, first.getValue());
		}
	}

	@Test
	void statementConsumerUpgradesSharedCaptureExactlyOnce(@TempDir Path directory) throws Exception {
		try (CountingValues values = new CountingValues(directory.toFile())) {
			IRI predicate = VF.createIRI("urn:test:lookup:predicate");
			values.startTransaction(true);
			long id = values.storeValue(predicate);
			values.commit();
			ValueConstant scalar = new ValueConstant(predicate);
			StatementPattern first = new StatementPattern(new Var("s"), Var.of("p", predicate), new Var("o"));
			StatementPattern second = first.clone();
			Join root = new Join(new Extension(new SingletonSet(), new ExtensionElem(scalar, "constant")),
					new Join(first, second));
			values.lookups = 0;
			new LmdbValueLookupOptimizer(values).optimize(root, null, EmptyBindingSet.getInstance());
			assertEquals(1, values.lookups, "all statement occurrences share one authoritative native lookup");
			assertSame(scalar.getValue(), first.getPredicateVar().getValue());
			assertSame(first.getPredicateVar().getValue(), second.getPredicateVar().getValue());
			LmdbValueVar prepared = (LmdbValueVar) first.getPredicateVar();
			assertTrue(prepared.isLmdbValueResolved());
			assertEquals(id, ((LmdbValue) prepared.getValue()).getInternalIdentity().id());
		}
	}

	@Test
	void finiteValuesCapturePreservesRowsWithoutResolvingUnusedColumns(@TempDir Path directory) throws Exception {
		try (CountingValues values = new CountingValues(directory.toFile())) {
			MapBindingSet row = new MapBindingSet();
			row.addBinding("unused", VF.createLiteral("finite unused value"));
			BindingSetAssignment assignment = new BindingSetAssignment();
			assignment.setDeclaredBindingNames(Set.of("unused", "optional"));
			assignment.setBindingSets(List.of(row, EmptyBindingSet.getInstance()));
			values.lookups = 0;
			new LmdbValueLookupOptimizer(values).optimize(assignment, null, EmptyBindingSet.getInstance());
			assertEquals(0, values.lookups, "finite VALUES capture is not native statement preparation");
			assertEquals(Set.of("unused", "optional"), assignment.getBindingNames(),
					"capture preserves declared nullable headers");
			assertEquals(Set.of("unused"), assignment.getPossibleBindingNames());
			var rows = assignment.getBindingSets().iterator();
			assertEquals(row, rows.next());
			assertEquals(EmptyBindingSet.getInstance(), rows.next());
			assertFalse(rows.hasNext());
		}
	}

	@Test
	void unknownValuesSourceIsNeverOpenedByPlanning(@TempDir Path directory) throws Exception {
		try (CountingValues values = new CountingValues(directory.toFile())) {
			AtomicInteger starts = new AtomicInteger();
			Iterable<BindingSet> source = () -> {
				starts.incrementAndGet();
				throw new AssertionError("a streaming binding source belongs to execution");
			};
			BindingSetAssignment assignment = new BindingSetAssignment();
			assignment.setDeclaredBindingNames(Set.of("x"));
			assignment.setBindingSets(source);
			assertDoesNotThrow(() -> new LmdbValueLookupOptimizer(values).optimize(assignment, null,
					EmptyBindingSet.getInstance()));
			assertEquals(0, starts.get());
			assertSame(source, assignment.getBindingSets());
		}
	}

	private static final class CountingValues extends ValueStore implements AutoCloseable {
		private int lookups;

		private CountingValues(File directory) throws IOException {
			super(new File(directory, "values"), new LmdbStoreConfig());
		}

		@Override
		public long getId(Value value, boolean create) throws IOException {
			if (!create) {
				lookups++;
			}
			return super.getId(value, create);
		}
	}
}
